// Mensaje que el cliente escribe por WhatsApp. Acepta los dos avisos de Chatwoot:
//  - Webhook (Integraciones → Webhooks, "Mensaje creado"): el cuerpo es el mensaje.
//  - Automatización ("Enviar evento de webhook"): el cuerpo es la conversación, con su último mensaje en messages[].
const b = $json.body || {};
let conv, msg;
if (b.event === 'message_created') {
  conv = b.conversation || {};
  msg = b;
} else if (b.event === 'automation_event.message_created') {
  // Solo "mensaje creado": la automatización también avisa cambios de estado, asignaciones, etc.
  conv = b;
  msg = (b.messages || [])[(b.messages || []).length - 1] || {};
} else {
  return [];
}
if (!(msg.message_type === 'incoming' || msg.message_type === 0) || msg.private === true) return [];
if (conv.channel !== 'Channel::Whatsapp') return [];

// Botones de la plantilla de alertas ("Dejar de recibir", "ALTA"…): los atiende "IAGRO · Seguimiento de estados"
const t = String(msg.content || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/^[^a-z0-9]+/, '').trim();
if (/^(dejar de recibir|no recibir alertas|desactivar alertas|activar alertas|recibir alertas|alta|solo lluvias fuertes|lluvias fuertes)$/.test(t)) return [];

// Un agente atiende el chat en Chatwoot: etiqueta "humano", o asignado y abierto en las últimas 6 h
const etiquetas = (conv.labels || []).map((x) => String(x).toLowerCase());
if (etiquetas.includes('humano')) return [];
if (conv.meta?.assignee && Number(conv.agent_last_seen_at || 0) * 1000 > Date.now() - 6 * 3600 * 1000) return [];

const sender = conv.meta?.sender || b.sender || {};
const telefono = String(sender.phone_number || '').replace(/\D/g, '');
if (telefono.length < 8 || !conv.id) return [];
// El mismo mensaje no se responde dos veces (Chatwoot puede avisar por webhook y por automatización)
const memoria = $getWorkflowStaticData('global');
const idMensaje = String(msg.id || '');
if (idMensaje) {
  memoria.atendidos = memoria.atendidos || {};
  if (memoria.atendidos[idMensaje]) return [];
  memoria.atendidos[idMensaje] = Date.now();
  const lista = Object.entries(memoria.atendidos);
  if (lista.length > 500) for (const [k] of lista.sort((a, b) => a[1] - b[1]).slice(0, lista.length - 500)) delete memoria.atendidos[k];
}
// Ubicación compartida con 📎 (o con el botón "Enviar ubicación")
const loc = (msg.attachments || []).find((a) => a.file_type === 'location' && a.coordinates_lat != null);
return [{ json: {
  telefono,
  conversation_id: conv.id,
  nombre_whatsapp: String(sender.name || '').trim(),
  texto: String(msg.content || ''),
  lat: loc ? Number(loc.coordinates_lat) : null,
  lon: loc ? Number(loc.coordinates_long) : null,
} }];

// Intención del mensaje, con reglas (sin IA). Los botones se reconocen por su título.
const m = $json;
const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[¿?¡!.,;:]/g, ' ').replace(/\s+/g, ' ').trim();
const s = norm(m.texto);
const sinIcono = s.replace(/^[^a-z0-9]+/, '').trim();   // "📡 ver radar" → "ver radar"
const DIAS = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
const BOTONES = {
  'mi ubicacion': 'PEDIR_UBICACION', 'enviar ubicacion': 'PEDIR_UBICACION', 'cambiar lote': 'PEDIR_UBICACION',
  'ver radar': 'RADAR', 'actualizar radar': 'RADAR',
  'manana': 'DIA', 'ver semana': 'SEMANA', 'actualizar': 'SEMANA', 'ver pronostico': 'SEMANA',
};

let intent = 'SEMANA', dia = null, codigo = null;
const saludo = /^(hola|hla|ola|buenas|buenos dias|buen dia|buenas tardes|buenas noches|holi)\b/.test(s);
const inv = s.match(/quiero alertas iagro\s+([a-z0-9]{4,8})/);

if (m.lat != null && m.lon != null) {
  intent = 'UBICACION_RECIBIDA';
} else if (inv) {
  intent = 'INVITACION';
  codigo = inv[1].toUpperCase();
} else if (BOTONES[sinIcono]) {
  intent = BOTONES[sinIcono];
  if (intent === 'DIA') dia = 'manana';
} else {
  if (/\bhoy\b/.test(s)) dia = 'hoy';
  else if (/\b(manana|mnn|mñn)\b/.test(s)) dia = 'manana';
  else dia = DIAS.find((d) => s.includes(d)) || null;

  if (/(fumig|riego|regar|plaga|precio|soya|vender|semilla|abono|insecticida|herbicida)/.test(s)) intent = 'FUERA';
  else if (/(cambiar (mi |el )?(lote|ubicacion|parcela)|otro lado|otra parcela|mi ubicacion|enviar ubicacion)/.test(s)) intent = 'PEDIR_UBICACION';
  else if (/(radar|donde .*llov|donde .*lluvia|ya viene|se acerca|ya llega|viene la lluvia)/.test(s)) intent = 'RADAR';
  else if (/(llov|lluv|yuev|aguacero|chubasco|tormenta)/.test(s) && !dia) intent = 'LLUVIA';
  else if (dia) intent = 'DIA';
  else if (/^(gracias|grax|muchas gracias|oki|ok|okey|ya|listo|dale|bueno|perfecto|genial)\b/.test(s) || /^[\u{1F44D}\u{1F64F}\u{1F44C}\u{1F60A}\s]+$/u.test(String(m.texto).trim())) intent = 'GRACIAS';
}
return [{ json: { ...m, intent, dia, codigo, saludo } }];

// Respuesta: un solo mensaje de servicio (imagen + texto + botones, o botón de enlace) para la API de WhatsApp
const m = $('Intención').first().json;
const cfg = $('Configuración').first().json.cfg || {};
const c = $('Cliente').first().json.c || {};
const p = $json || {};                                  // respuesta del panel: { dias, imagen } o un error
const SITIO = 'https://iagro360.xyz';
const conLote = c.lat != null && c.lon != null;
const dias = Array.isArray(p.dias) ? p.dias : [];
const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const fmtMm = (mm) => (mm >= 1 ? String(Math.round(mm)) : Number(mm).toFixed(1));
const nombre = /[a-záéíóúñ]/i.test(m.nombre_whatsapp) ? m.nombre_whatsapp.split(/\s+/)[0] : '';

const lugar = conLote ? 'tu ubicación' : 'Santa Cruz';
const pie = conLote ? 'IAGRO · Según tu ubicación' : 'IAGRO · Santa Cruz (general)';
const PEDIR = '\n\n👉 Este pronóstico es de *Santa Cruz en general*. Para el de *tu lote*, toca *📍 Mi ubicación*.';
const B = { ubic: '📍 Mi ubicación', radar: '📡 Ver radar', manana: '📅 Mañana', semana: '📅 Ver semana', actualizar: '🔄 Actualizar' };
// Sin ubicación, el primer botón siempre la pide
const nav = (a, b) => (conLote ? [a, b] : [B.ubic, a]);

const to = m.telefono;
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };
const conBotones = (texto, lista, imagen) => ({ ...base, type: 'interactive', interactive: {
  type: 'button',
  ...(imagen ? { header: { type: 'image', image: { link: imagen } } } : {}),
  body: { text: texto.slice(0, 1024) },
  footer: { text: pie },
  action: { buttons: lista.slice(0, 3).map((t, i) => ({ type: 'reply', reply: { id: 'b' + (i + 1), title: t } })) },
} });
const conEnlace = (texto, boton, url) => ({ ...base, type: 'interactive', interactive: {
  type: 'cta_url', body: { text: texto.slice(0, 1024) }, footer: { text: pie },
  action: { name: 'cta_url', parameters: { display_text: boton, url } },
} });
const pedirUbicacion = (texto) => ({ ...base, type: 'interactive', interactive: {
  type: 'location_request_message', body: { text: texto }, action: { name: 'send_location' },
} });
const soloTexto = (texto) => ({ ...base, type: 'text', text: { body: texto, preview_url: false } });

// ---------- Textos con el pronóstico ----------
const proxima = dias.find((d) => d.mm >= 1);
const iProx = proxima ? dias.indexOf(proxima) : -1;
const cuando = (d) => (dias.indexOf(d) === 0 ? 'hoy' : dias.indexOf(d) === 1 ? 'mañana' : d.nombre.toLowerCase() + ' ' + d.ddmm);

function semana() {
  let t = proxima
    ? '🌧️ Lluvia en ' + lugar + ': *' + cuando(proxima) + (proxima.inicio ? ' desde las ' + proxima.inicio : '') + ', unos ' + fmtMm(proxima.mm) + ' mm*' + (proxima.prob ? ' (' + proxima.prob + '%)' : '') + '.'
    : '☀️ Sin lluvias importantes en ' + lugar + ' en los próximos días.';
  const antes = iProx === -1 ? dias.slice(0, 7) : dias.slice(0, iProx);
  const calor = antes.length ? Math.max(...antes.map((d) => d.max ?? -99)) : -99;
  if (iProx >= 2) t += '\nAntes, ' + iProx + ' días secos' + (calor >= 35 ? ' y con calor (hasta ' + calor + '°)' : '') + '.';
  else if (iProx === -1 && calor >= 35) t += '\nCon calor: hasta ' + calor + '°.';
  if (dias.slice(0, 3).filter((d) => d.viento >= 20).length >= 2) t += '\n⚠️ Viento fuerte estos días: no conviene fumigar.';
  return t;
}

function delDia() {
  const i = m.dia === 'hoy' ? 0 : m.dia === 'manana' ? 1 : dias.findIndex((d) => norm(d.nombre) === m.dia);
  const d = dias[i < 0 ? 0 : i];
  const etiqueta = i <= 0 ? 'Hoy' : i === 1 ? 'Mañana' : d.nombre;
  let t = '📍 ' + (conLote ? 'Tu ubicación' : 'Santa Cruz (general)') + '\n*' + etiqueta + ' ' + d.ddmm + ':* ' + (d.min ?? '–') + '° a ' + (d.max ?? '–') + '°\n';
  t += d.mm >= 1 ? '🌧️ Lluvia' + (d.inicio ? ' desde las ' + d.inicio : '') + ', unos ' + fmtMm(d.mm) + ' mm' + (d.prob ? ' (' + d.prob + '%)' : '') + '.'
    : d.mm > 0 ? '🌦️ Apenas unas gotas (' + fmtMm(d.mm) + ' mm).' : '☀️ Sin lluvia.';
  t += '\n💨 Viento ' + d.viento + ' km/h' + (d.dir ? ' ' + d.dir : '') + '.';
  if (d.viento >= 20) t += ' No conviene fumigar.';
  else if (d.mm < 1) t += ' Buen día para aplicar, temprano.';
  return t;
}

function lluvia() {
  if (!proxima) return '☀️ Sin lluvias importantes en ' + lugar + ' en los próximos ' + dias.length + ' días.';
  let t = '🌧️ Próxima lluvia en ' + lugar + ':\n*' + cuando(proxima).replace(/^./, (x) => x.toUpperCase()) + (proxima.inicio ? ' desde las ' + proxima.inicio : '') + ', unos ' + fmtMm(proxima.mm) + ' mm*' + (proxima.prob ? ' (' + proxima.prob + '%)' : '') + '.';
  if (iProx >= 2) t += '\nAntes, ' + iProx + ' días secos.';
  return t;
}

// ---------- Respuesta según la intención ----------
const radarUrl = SITIO + '/radar/' + (conLote && c.id ? c.id : 'santa-cruz');
const imagen = p.imagen ? SITIO + p.imagen : null;
const NECESITA_DATOS = ['SEMANA', 'DIA', 'LLUVIA', 'UBICACION_RECIBIDA', 'INVITACION'];
let cuerpo, resumen;

if (NECESITA_DATOS.includes(m.intent) && !dias.length) {
  resumen = '⚠️ No pude traer el pronóstico en este momento. Intenta de nuevo en unos minutos.';
  cuerpo = conBotones(resumen, [B.actualizar, B.radar]);
} else if (m.intent === 'RADAR') {
  resumen = '📡 Radar de lluvia en vivo ' + (conLote ? 'centrado en *tu ubicación*' : 'de *Santa Cruz*') + '. Toca el botón para verlo y mover el mapa.'
    + (conLote ? '' : '\n\nPara verlo sobre tu lote, envíame tu ubicación con 📎.');
  cuerpo = conEnlace(resumen, 'Ver radar', radarUrl);
} else if (m.intent === 'PEDIR_UBICACION') {
  resumen = '📍 Toca *Enviar ubicación* y elige el punto de tu lote (puedes mover el mapa hasta tu parcela). Solo la usamos para tu pronóstico y tu radar.';
  cuerpo = pedirUbicacion(resumen);
} else if (m.intent === 'GRACIAS') {
  resumen = '¡A la orden' + (nombre ? ', ' + nombre : '') + '! 🌾 Escríbeme *lluvia*, *mañana* o *radar* cuando quieras.';
  cuerpo = soloTexto(resumen);
} else if (m.intent === 'FUERA') {
  resumen = 'Por ahora solo te ayudo con el *pronóstico* y el *radar* de lluvia 🌦️';
  cuerpo = conBotones(resumen, nav(B.semana, B.radar));
} else if (m.intent === 'DIA') {
  resumen = delDia() + (conLote ? '' : PEDIR);
  cuerpo = conBotones(resumen, nav(B.semana, B.radar));
} else if (m.intent === 'LLUVIA') {
  resumen = lluvia() + (conLote ? '' : PEDIR);
  cuerpo = conBotones(resumen, nav(B.radar, B.semana));
} else {
  // SEMANA, UBICACION_RECIBIDA, INVITACION: el primer mensaje, con la imagen de 7 días
  let antes = '';
  if (m.intent === 'UBICACION_RECIBIDA') antes = '✅ *Ubicación ' + (c.nuevo ? 'guardada' : 'actualizada') + '.* Desde ahora te muestro el pronóstico de ese punto.\n\n';
  else if (m.intent === 'INVITACION') antes = '¡Hola' + (nombre ? ' ' + nombre : '') + '! 👋 Te invitaron a *IAGRO*: pronóstico y radar de lluvia para tu campo.\n\n';
  else if (m.saludo) antes = '¡Hola' + (nombre ? ' ' + nombre : '') + '! 👋\n\n';
  resumen = antes + semana() + (conLote ? '' : PEDIR);
  cuerpo = conBotones(resumen, conLote ? [B.radar, B.manana, B.actualizar] : [B.ubic, B.radar, B.manana], imagen);
}

return [{ json: {
  meta_url: 'https://graph.facebook.com/' + String(cfg.whatsapp_api_version || 'v25.0').trim() + '/' + String(cfg.whatsapp_phone_number_id || '1356446567560317').trim() + '/messages',
  meta_cuerpo: cuerpo,
  resumen,
  chatwoot: String(cfg.chatwoot_url_publica || '').replace(/\/+$/, '') + '/api/v1/accounts/' + cfg.chatwoot_account_id + '/conversations/' + m.conversation_id + '/messages',
} }];

// Por qué Meta no aceptó el mensaje (queda como nota privada en Chatwoot)
const e = $json.error || $json;
let detalle = e.description || e.message || '';
try {
  const x = typeof e.description === 'string' && e.description.match(/\{[\s\S]*\}/);
  const j = x ? JSON.parse(x[0]) : null;
  if (j?.error) detalle = '(#' + j.error.code + ') ' + (j.error.error_data?.details || j.error.message);
} catch (_) { /* se deja el texto tal cual */ }
return [{ json: { motivo: String(e.httpCode ? 'HTTP ' + e.httpCode + ' · ' : '') + String(detalle || JSON.stringify(e)).slice(0, 500) } }];
